function Assert-Exact([string]$Name,$Actual,$Expected){if($null -eq $Actual -and $null -eq $Expected){return};if($null -eq $Actual -or $null -eq $Expected -or $Actual -cne $Expected){throw "Bob Tin persisted-state $Name differs: expected '$Expected', actual '$Actual'."}}
function Assert-Double([string]$Name,$Actual,$Expected){if([Math]::Abs(([double]$Actual)-([double]$Expected)) -gt 0.000001){throw "Bob Tin persisted-state $Name differs: expected '$Expected', actual '$Actual'."}}
function Assert-Props([string]$Name,$Object,[string[]]$Expected){if($null -eq $Object){throw "Bob Tin persisted-state $Name is absent."};$actual=@($Object.PSObject.Properties.Name|Sort-Object);$wanted=@($Expected|Sort-Object);if(($actual -join "`n") -cne ($wanted -join "`n")){throw "Bob Tin persisted-state $Name properties differ."}}
function Assert-Array([string]$Name,$Actual,[string[]]$Expected){$values=@($Actual|ForEach-Object{[string]$_});if(($values -join "`n") -cne ($Expected -join "`n")){throw "Bob Tin persisted-state $Name differs."}}
function ConvertTo-Canonical($Value){if($null -eq $Value){return $null};if($Value -is [string]){return [string]$Value};if($Value -is [System.Collections.IDictionary]){$out=[ordered]@{};foreach($key in @($Value.Keys|ForEach-Object{[string]$_}|Sort-Object)){$out[$key]=ConvertTo-Canonical $Value[$key]};return $out};if($Value -is [pscustomobject]){$out=[ordered]@{};foreach($property in @($Value.PSObject.Properties.Name|Sort-Object)){$out[$property]=ConvertTo-Canonical $Value.$property};return $out};if($Value -is [System.Collections.IEnumerable]){$items=@($Value|ForEach-Object{ConvertTo-Canonical $_});return ,$items};return $Value}
function Copy-Observation($Value){return (ConvertTo-Canonical $Value|ConvertTo-Json -Depth 30|ConvertFrom-Json)}
