function Assert-StateObservation($Observation,[string]$ExpectedStage,[int]$ExpectedGeneration,[int]$ExpectedPredecessor){Assert-Props "observation.$ExpectedStage" $Observation @('stage','generation','predecessor_generation','completed_levels','current_research_technology_level','current_research','queue','fractional_progress','observed_effect_change','derived_earned_modifier','raw_direct_max_level','mirset1_imported_max_level','effective_max_level','policy_binding_count','policy_setting','policy_technology');Assert-Exact "$ExpectedStage.stage" $Observation.stage ($ExpectedStage.ToLowerInvariant());Assert-Exact "$ExpectedStage.generation" $Observation.generation $ExpectedGeneration;Assert-Exact "$ExpectedStage.predecessor" $Observation.predecessor_generation $ExpectedPredecessor;Assert-Exact "$ExpectedStage.completed" $Observation.completed_levels $dossier.persisted_state.completed_levels;Assert-Exact "$ExpectedStage.current_level" $Observation.current_research_technology_level $dossier.persisted_state.current_research_technology_level;Assert-Exact "$ExpectedStage.current" $Observation.current_research $dossier.persisted_state.current_research;Assert-Array "$ExpectedStage.queue" $Observation.queue @($dossier.persisted_state.queue);Assert-Double "$ExpectedStage.progress" $Observation.fractional_progress $dossier.persisted_state.fractional_progress;Assert-Double "$ExpectedStage.effect" $Observation.observed_effect_change $dossier.anchor.effect_change_per_completed_level;Assert-Double "$ExpectedStage.derived" $Observation.derived_earned_modifier $dossier.persisted_state.derived_earned_modifier;Assert-Double "$ExpectedStage.derived formula" $Observation.derived_earned_modifier ($Observation.completed_levels*$Observation.observed_effect_change);Assert-Exact "$ExpectedStage.raw" $Observation.raw_direct_max_level $dossier.cap_transport.raw_direct_max_level;Assert-Exact "$ExpectedStage.imported" $Observation.mirset1_imported_max_level $dossier.cap_transport.mirset1_imported_