function Assert-DriftNegatives($Initial,$CycleOne,$CycleTwo,$Terminal){$drifts=@(@{value=(Copy-Observation $Initial);property='fractional_progress';replacement=0.41;stage='INITIAL';generation=0;predecessor=-1},@{value=(Copy-Observation $CycleOne);property='generation';replacement=2;stage='CYCLE';generation=1;predecessor=0},@{value=(Copy-Observation $CycleTwo);property='policy_binding_count';replacement=2;stage='CYCLE';generation=2;predecessor=1},@{value=(Copy-Observation $Terminal);property='queue';replacement=@('unexpected');stage='TERMINAL';generation=2;predecessor=1});foreach($drift in $drifts){$drift.value.($drift.property)=$drift.replacement;$caught=$false;try{Assert-StateObservation $drift.value $drift.stage $drift.generation $drift.predecessor}catch{$caught=$true};if(-not $caught){throw "Bob Tin persisted-state drift negative for $($drift.property) was accepted."}};$control=Get-Content -Raw -LiteralPath (Join-Path $fixture 'control.lua');if($control -notmatch 'game[.]server_save\(save_name\)' -or $control -notmatch 'loaded_generation = state and state[.]generation or nil' -or $control -notmatch 'state[.]generation ~= loaded_generation' -or $control -notmatch 'loaded_generation == 0' -or $control -notmatch 'loaded_generation == 1'){throw 'Bob Tin persisted-state one-transition-per-process guard is absent.'}}

