function Invoke-PersistedEngine([string]$Name,[string[]]$Arguments){$factorioLog=Join-Path $userdata 'factorio-current.log';if(Test-Path -LiteralPath $factorioLog){Remove-Item -LiteralPath $factorioLog -Force};$start=[Diagnostics.ProcessStartInfo]::new($engine);$start.UseShellExecute=$false;$start.CreateNoWindow=$true;$start.WindowStyle=[Diagnostics.ProcessWindowStyle]::Hidden;$start.Environment['SteamAppId']='427520';$start.Environment['SteamGameId']='427520';$start.RedirectStandardOutput=$true;$start.RedirectStandardError=$true;foreach($argument in @('--config',(Join-Path $run 'config.ini'),'--no-log-rotation','--disable-audio','--mod-directory',$mods)+$Arguments){[void]$start.ArgumentList.Add($argument)};$process=[Diagnostics.Process]::Start($start);try{$stdout=$process.StandardOutput.ReadToEndAsync();$stderr=$process.StandardError.ReadToEndAsync();if(-not $process.WaitForExit(120000)){$process.Kill($true);throw "Bob Tin persisted-state engine timeout: $run"};$text=$stdout.GetAwaiter().GetResult()+$stderr.GetAwaiter().GetResult();[IO.File]::WriteAllText((Join-Path $run "engine-$Name.log"),$text,[Text.UTF8Encoding]::new($false));if($process.ExitCode -ne 0){throw "Bob Tin persisted-state engine failed during ${Name}: $run`n$($text.Substring([Math]::Max(0,$text.Length-2500)))"}}finally{$process.Dispose()};if(-not(Test-Path -LiteralPath $factorioLog -PathType Leaf)){throw "Bob Tin persisted-state Factorio log absent after $Name"};$copy=Join-Path $run "factorio-$Name.log";Copy-Item -LiteralPath $factorioLog -Destination $copy;return $copy}
function Invoke-PersistedServerSave([string]$Name,[string]$InputSave,[string]$SavedMapPath){$factorioLog=Join-Path $userdata 'factorio-current.log';if(Test-Path -LiteralPath $factorioLog){Remove-Item -LiteralPath $factorioLog -Force};$start=[Diagnostics.ProcessStartInfo]::new($engine);$start.UseShellExecute=$false;$start.CreateNoWindow=$true;$start.WindowStyle=[Diagnostics.ProcessWindowStyle]::Hidden;$start.Environment['SteamAppId']='427520';$start.Environment['SteamGameId']='427520';foreach($argument in @('--config',(Join-Path $run 'config.ini'),'--no-log-rotation','--disable-audio','--mod-directory',$mods,'--server-settings',(Join-Path $run 'server-settings.json'),'--start-server',$InputSave)){[void]$start.ArgumentList.Add($argument)};$process=[Diagnostics.Process]::Start($start);$ready=$false;try{$deadline=[DateTime]::UtcNow.AddSeconds(45);while([DateTime]::UtcNow -lt $deadline){if($process.HasExited){throw "Bob Tin persisted-state server exited before save during $Name with code $($process.ExitCode)."};if((Test-Path -LiteralPath $factorioLog -PathType Leaf) -and (Test-Path -LiteralPath $SavedMapPath -PathType Leaf)){$text=Get-Content -Raw -LiteralPath $factorioLog;if($text.Contains('[mir-bob-tin-persisted-state] CYCLE JSON') -and $text.Contains('Hosting game') -and $text.Contains('Saving finished')){$ready=$true;break}};Start-Sleep -Milliseconds 200};if(-not $ready){throw "Bob Tin persisted-state server did not materialize successor during ${Name}: $run"}}finally{if(-not $process.HasExited){try{$process.Kill($true)}catch{$process.Kill()}};$process.WaitForExit();$process.Dispose()};$copy=Join-Path $run "factorio-$Name.log";Copy-Item -LiteralPath $factorioLog -Destination $copy;return $copy}
